var letterText="Dear Asmita,\n\nSo, detective, you finally found me.\n\nI know this entire investigation was a little dramatic, but some people deserve more than an ordinary message.\n\nYou are one of the most important people in my life. I hope you never underestimate the value you bring into the lives of people around you.\n\nWhenever life gets difficult, whenever you need someone to listen, celebrate your smallest achievements, or simply sit with you in silence — you can count on me.\n\nYou do not have to pretend to be happy around me. You do not have to be perfect. Just be yourself.\n\nYour happiness matters. Your feelings matter. You matter.\n\nThank you for being you, Asmita. If this friendship were a game, I would choose you as my teammate in every single lifetime.\n\nWith lots of care and a little bit of teasing,\n\n— Abhay";
function zoneAt(x){for(var i=0;i<zones.length;i++)if(x<zones[i].end)return zones[i];return zones[zones.length-1]}
function fresh(){return{version:2,started:false,x:120,clues:[],safeKey:false,portalReady:false,letter:false,visited:[],health:3,checkpoint:120,caveSeen:false,endingDone:false,routeSolved:false}}
function norm(s){var q=fresh();if(!s||typeof s!=="object")return q;Object.assign(q,s);q.version=2;q.clues=Array.from(new Set(Array.isArray(q.clues)?q.clues:[]));q.visited=Array.isArray(q.visited)?q.visited:[];q.health=Math.max(1,Math.min(3,Number(q.health)||3));q.x=Math.max(0,Math.min(12300,Number(q.x)||120));q.checkpoint=Math.max(0,Math.min(12300,Number(q.checkpoint)||q.x));return q}
function migrate(){if(qa)return fresh();try{var old=JSON.parse(localStorage.getItem("last-clue-save"));if(!old)return fresh();var c=Array.isArray(old.clues)?old.clues:[],x=120;if(old.letter)x=10430;else if(c.includes("key")||old.safeKey)x=7980;else if(c.includes("ticket"))x=6460;else if(c.includes("photo"))x=4910;else if(c.includes("notebook"))x=3260;else if(c.includes("message")||old.scene>0)x=1530;return norm({version:2,started:true,x:x,checkpoint:x,clues:c,safeKey:!!old.safeKey,portalReady:!!old.portalReady,letter:!!old.letter,caveSeen:old.scene>=6,visited:[]})}catch(e){return fresh()}}
function load(){try{var n=localStorage.getItem(SAVE_KEY);if(n)return norm(JSON.parse(n))}catch(e){}return migrate()}
var state=load(),p={x:state.x,y:FLOOR,vx:0,vy:0,facing:1,grounded:true,walk:0,invuln:0},cameraX=0,lastTime=performance.now(),time=0,keys={left:false,right:false,run:false},jumpQueued=false,attackQueued=false,attackTime=0,combat={active:false,enemyHp:3,phase:"wait",timer:1.2,attackCooldown:0},revealActive=false,dialogueQueue=[],dialogueDone=null,dialogueOpen=false,toastTimer=0,transition="",transitionAt=0,cinematic=false,endingPhase="",endingAt=0,endingStartX=0,endingTalk=false,keeperHearts=3,routeSolved=!!state.routeSolved,soundOn=true,musicOn=false,audioCtx=null,visitedZone=zoneAt(p.x).id;
function save(){state.version=2;state.x=Math.round(p.x);state.routeSolved=routeSolved;try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));var el=document.getElementById("saveStatus");if(el)el.textContent="AUTO-SAVED"}catch(e){}updateHud()}
function evidence(){return["notebook","photo","ticket","key"].filter(function(k){return state.clues.includes(k)}).length}
