function openPanel(html,buttons){card.innerHTML=html+(buttons&&buttons.length?'<div class="actions">'+buttons.map(function(b,i){return'<button class="pixel-btn '+(b.secondary?"secondary":"")+'" data-act="'+i+'">'+b.label+'</button>'}).join("")+"</div>":"");overlay.classList.remove("closed");card.querySelectorAll("[data-act]").forEach(function(el){el.onclick=function(){var b=buttons[Number(el.dataset.act)];if(b&&b.fn)b.fn()}})}
function closePanel(){overlay.classList.add("closed")}
function showTalk(lines,done){dialogueQueue=lines.slice();dialogueDone=done||null;nextTalk()}
function nextTalk(){if(!dialogueQueue.length){dialogueOpen=false;dialogue.classList.add("hidden");var f=dialogueDone;dialogueDone=null;if(f)f();return}var a=dialogueQueue.shift();dialogueOpen=true;speakerEl.textContent=a[0];lineEl.textContent=a[1];portraitEl.innerHTML=portrait(a[0]);dialogue.classList.remove("hidden")}
