function opening(){updateHud();if(state.started){openPanel('<div class="title-hero"><div class="title-art">'+portrait("ASMITA")+'</div><div><div class="eyebrow">YOUR ADVENTURE IS SAVED</div><h1>THE LAST<br>CLUE</h1><p class="subtitle">Run, jump, explore — and follow the story to the sunset.</p><p>Continue from '+zoneAt(p.x).name.toLowerCase()+'. Your older save has been preserved.</p></div></div>',[{label:"CONTINUE ADVENTURE",fn:function(){closePanel();save();if(!state.visited.length)intro() }},{label:"NEW ADVENTURE",secondary:true,fn:function(){openPanel('<div class="eyebrow">START OVER</div><h2>Begin a new adventure?</h2><p>Your current run stays saved. This starts a fresh run.</p>',[{label:"START FRESH RUN",fn:startNew},{label:"KEEP THIS SAVE",secondary:true,fn:opening}])}}]);return}
openPanel('<div class="title-hero"><div class="title-art">'+portrait("ASMITA")+'</div><div><div class="eyebrow">AN ORIGINAL 2D ADVENTURE</div><h1>THE LAST<br>CLUE</h1><p class="subtitle">Run, jump, explore — and follow the story to the sunset.</p><p>Asmita has a message to find. Abhay is waiting at the end of the trail.</p></div></div>',[{label:"START ADVENTURE",fn:startNew}])}
function intro(){showTalk([["NARRATOR","A folded letter waits beneath the streetlamp. Its first clue points toward the old library."],["ASMITA","Someone went to a lot of trouble to get my attention. All right, let’s follow the trail."]])}
function startNew(){state=fresh();state.started=true;p.x=120;p.y=FLOOR;p.vx=0;p.vy=0;p.grounded=true;visitedZone="town";closePanel();save();intro()}
function menu(){openPanel('<div class="eyebrow">PAUSE</div><h2>Take a breath, detective.</h2><p>Your progress is saved. Keep exploring, check the field notes, or start a fresh run.</p>',[{label:"RESUME",fn:closePanel},{label:"FIELD NOTES",secondary:true,fn:notebook},{label:"FRESH RUN",secondary:true,fn:function(){openPanel('<div class="eyebrow">NEW RUN</div><h2>Start a fresh adventure?</h2><p>The current run stays saved.</p>',[{label:"START FRESH",fn:startNew},{label:"GO BACK",secondary:true,fn:menu}])}}])}
document.getElementById("pauseBtn").onclick=menu;document.getElementById("notebookBtn").onclick=notebook;
function notebook(){var names={notebook:"The library notebook",photo:"The park photograph",ticket:"The train ticket",key:"The safe’s final clue"};openPanel('<div class="eyebrow">FIELD NOTES · '+evidence()+'/4 CLUES</div><h2>Evidence in the case file</h2><ol class="clue-list">'+["notebook","photo","ticket","key"].map(function(k){return"<li>"+(state.clues.includes(k)?"<b>"+names[k]+"</b>":"??? — Still out there")+"</li>"}).join("")+'</ol><p>Streetlamp letter: '+(state.clues.includes("message")?"filed.":"not found yet.")+'</p>',[{label:"BACK TO THE ADVENTURE",fn:closePanel}])}
var inv=document.createElement("button");inv.className="hud-btn";inv.textContent="◇";inv.setAttribute("aria-label","Open inventory");inv.onclick=function(){var items=state.clues.map(function(k){return{message:"Folded letter",notebook:"Library notebook",photo:"Photograph",ticket:"Train ticket",key:"Cliff clue"}[k]||k});if(state.safeKey)items.push("Brass safe key");openPanel('<div class="eyebrow">INVENTORY</div><h2>Pockets & keepsakes</h2><ul class="clue-list">'+(items.length?items.map(function(v){return"<li>"+v+"</li>"}).join(""):"<li>Your notebook is waiting for its first clue.</li>")+'</ul>',[{label:"BACK",fn:closePanel}])};document.querySelector(".hud").insertBefore(inv,document.getElementById("hearts"));
function clearChallenge(){challengeTimers.forEach(clearTimeout);challengeTimers=[]}
var challengeTimers=[];
function showSignal(){var seq=[2,0,3,1],idx=0,ready=false;function draw(){openPanel('<div class="eyebrow">STREETLAMP SIGNAL</div><h2>Repeat the four-light rhythm</h2><p>Watch the lamp colors, then tap them in the same order.</p><div class="challenge-stage"><div class="signal-lights">'+["✦","●","◆","▲"].map(function(v,i){return'<button data-light="'+i+'">'+v+'</button>'}).join("")+'</div><div class="puzzle-readout" id="readout">Watch the sequence…</div></div>',[{label:"CLOSE",secondary:true,fn:function(){clearChallenge();closePanel()}}]);card.querySelectorAll("[data-light]").forEach(function(b){b.onclick=function(){if(!ready)return;var i=Number(b.dataset.light);if(i!==seq[idx]){idx=0;ready=false;playSound(220,.1);showSequence(true);return}b.classList.add("lit");setTimeout(function(){b.classList.remove("lit")},170);if(++idx===seq.length)collect("message","The hidden letter says to look for a thought tucked inside the old library.");}});
showSequence(false)}function showSequence(retry){ready=false;idx=0;var r=document.getElementById("readout");if(r)r.textContent=retry?"The rhythm resets. Watch again.":"Watch the sequence…";card.querySelectorAll("[data-light]").forEach(function(b){b.disabled=true});seq.forEach(function(n,i){challengeTimers.push(setTimeout(function(){var b=card.querySelector('[data-light="'+n+'"]');if(b)b.classList.add("lit");challengeTimers.push(setTimeout(function(){if(b)b.classList.remove("lit")},330))},500+i*650))});challengeTimers.push(setTimeout(function(){ready=true;var e=document.getElementById("readout");if(e)e.textContent="Your turn — repeat it";card.querySelectorAll("[data-light]").forEach(function(b){b.disabled=false})},500+seq.length*650))}draw()}
function showCipher(){var pieces=["YOU ARE NOT ALONE","A PROMISE","WHENEVER YOU NEED ME"],order=[1,2,0],picked=[];function draw(note){openPanel('<div class="eyebrow">LIBRARY RETURN-CART CIPHER</div><h2>Rebuild the margin note</h2><p>The librarian points to the clue: a promise belongs first; reassurance belongs last.</p><div class="challenge-stage"><div class="sequence-note">“A friend’s promise is complete when it ends with reassurance.”</div><div class="sequence-tiles">'+pieces.map(function(v,i){return'<button data-piece="'+i+'">'+v+'</button>'}).join("")+'</div><div class="puzzle-readout">'+(picked.length?picked.map(function(i){return pieces[i]}).join(" → "):"Arrange three paper strips in order.")+'</div>'+(note?'<p class="danger">'+note+'</p>':"")+'</div>',[{label:"RESET",secondary:true,fn:function(){picked=[];draw()}},{label:"CLOSE",secondary:true,fn:closePanel}]);card.querySelectorAll("[data-piece]").forEach(function(b){b.onclick=function(){var i=Number(b.dataset.piece);if(picked.includes(i))return;if(i!==order[picked.length]){picked=[];draw("That fragment does not fit. Start with the promise.");return}picked.push(i);if(picked.length===3){collect("notebook","The notebook confirms Abhay wanted Asmita to know she is never alone.");return}draw()}})}draw()}
function showStationPuzzle(){var v=[0,0,0],sol=[1,0,1];function draw(note){openPanel('<div class="eyebrow">STATION SIGNAL CABIN</div><h2>Route the train to the lit platform</h2><p>Match the painted arrow marks above the track.</p><div class="challenge-stage"><div class="rail-map">'+v.map(function(a,i){return'<button class="rail-switch" data-sw="'+i+'"><small>POINT '+(i+1)+'</small><b>'+(a?"↗":"↖")+'</b></button>'}).join('<span class="rail-link">━━</span>')+'</div><div class="puzzle-readout">ROUTE: ↗ · ↖ · ↗</div>'+(note?'<p class="danger">'+note+'</p>':"")+'</div>',[{label:"SEND THE TRAIN",fn:function(){if(v.every(function(a,i){return a===sol[i]})){routeSolved=true;state.routeSolved=true;save();collect("ticket","The train slows. Its ticket points to a brass key, a cave, and the cliff at sunset.");return}draw("Wrong track. Compare the three painted arrows and try again.")}},{label:"RESET SWITCHES",secondary:true,fn:function(){v=[0,0,0];draw()}},{label:"CLOSE",secondary:true,fn:closePanel}]);card.querySelectorAll("[data-sw]").forEach(function(b){b.onclick=function(){var i=Number(b.dataset.sw);v[i]=1-v[i];draw()}})}draw()}
function showDuel(){if(state.safeKey){showTalk([["KEEPER","The safe is right behind me. Don’t let it win."]]);return}combat={active:true,enemyHp:3,phase:"wait",timer:1.2,attackCooldown:0};p.facing=p.x<6970?1:-1;showTalk([["KEEPER","Three clean hits and the safe key is yours. Watch my shoulders before I swing."],["ASMITA","Deal. And no going easy on me."]]);toast("Rooftop spar: press J or ACT to strike; jump over his swing.")}
function showSafeDial(){var v=[0,0,0],sym=["☾","❧","☀","✦"],sol=[0,1,2];function draw(note){openPanel('<div class="eyebrow">THE ROOFTOP SAFE</div><h2>Match the marks from the ticket</h2><p>The note reads: crescent, leaf, sun.</p><div class="challenge-stage"><div class="lock-wheels">'+v.map(function(a,i){return'<button class="lock-wheel" data-dial="'+i+'"><small>▲</small><b>'+sym[a]+'</b><small>▼</small></button>'}).join("")+'</div><div class="puzzle-readout">☾ · ❧ · ☀</div>'+(note?'<p class="danger">'+note+'</p>':"")+'</div>',[{label:"TEST THE SAFE",fn:function(){if(v.every(function(a,i){return a===sol[i]})){collect("key","Inside the safe is a note: the cave exit opens on the sunset cliff.");return}draw("The lock resists. Use the symbols in order: crescent, leaf, sun.")}},{label:"RESET",secondary:true,fn:function(){v=[0,0,0];draw()}},{label:"CLOSE",secondary:true,fn:closePanel}]);card.querySelectorAll("[data-dial]").forEach(function(b){b.onclick=function(){var i=Number(b.dataset.dial);v[i]=(v[i]+1)%sym.length;draw()}})}draw()}
function allEvidence(){return evidence()===4}
function collect(id,text){clearChallenge();closePanel();if(state.clues.includes(id)){toast("Already filed in the notebook.");return}state.clues.push(id);if(id==="key")state.portalReady=allEvidence();save();showTalk([["ASMITA",text]],function(){if(id==="key"&&allEvidence()){state.portalReady=true;save();openPanel('<div class="eyebrow">ALL FOUR CLUES CONNECT</div><h2>A doorway opens above the city</h2><p>The letter, notebook, photograph and ticket point to the same place. A blue-gold portal shimmers at the far rooftop.</p><div class="portal-card"><span>✦</span><div><b>KEEP EXPLORING</b><small>Run to the glowing gate. The next area lies beyond it.</small></div></div>',[{label:"KEEP PLAYING",fn:closePanel}])}else toast("Clue filed. Keep walking to the next gate.")})}
function nearestAction(){var a=[["message",970,398],["notebook",2780,435],["photo",4520,353],["switchboard",5360,428],["ticket",6000,419],["keeper",6970,FLOOR],["safe",7525,435]],best=null,dist=1e9;for(var i=0;i<a.length;i++){var id=a[i][0];if(state.clues.includes(id))continue;if(id==="ticket"&&!routeSolved)continue;if(id==="photo"&&p.y>390)continue;if(id==="safe"&&!state.safeKey){/* keep it inspectable so it explains the missing key */}var d=Math.hypot(p.x-a[i][1],(p.y-45)-a[i][2]);if(d<100&&d<dist){best=id;dist=d}}return best}
