function enterZone(z){if(z.id===visitedZone)return;visitedZone=z.id;state.checkpoint=Math.max(0,z.start+45);state.visited.push(z.id);save();toast(z.name);var lines={library:[["NARRATOR","The old library smells of cedar shelves. Readers drift between the stacks."],["ASMITA","A note in the margins should tell me where to go next."]],park:[["NARRATOR","The library path opens into a leafy park. A photograph flutters above the raised trail."],["ASMITA","Those ledges look deliberate. Someone wants me to follow them."]],station:[["NARRATOR","The park path meets the old station. A train waits behind a chain of signal switches."],["ASMITA","Route it to the lit platform and maybe the ticket is still aboard."]],roof:[["NARRATOR","The station stairs climb above the rooftops. A keeper watches a brass safe in the wind."],["ASMITA","This is either a dramatic clue or a stubborn lock."]],cave:[["NARRATOR","The portal opens into a winding cave. Crystals shine along the walls; gold rays slip through cracks overhead."]],cliff:[["NARRATOR","The cave mouth opens onto mountains and an enormous sunset. The grass moves softly in the wind."]]};if(lines[z.id])showTalk(lines[z.id])}
