function openLetter(){state.letter=true;save();openPanel('<div class="eyebrow">A LETTER FOR ASMITA</div><div class="letter">'+letterText+'</div><p class="small">The wind moves softly through the cave mouth. Take your time.</p>',[{label:"TAKE ABHAY’S HAND",fn:function(){closePanel();beginEnding()}}])}
