function endCard(){openPanel('<div class="eyebrow">✦ YOU FOUND YOUR FINAL CLUE ✦</div><h2>Some mysteries end with answers.</h2><p>Some adventures end with memories. And some friendships are worth keeping forever.</p><p class="subtitle">But this friendship? It’s an ongoing story.</p><p><b>— Abhay</b></p>',[{label:"PLAY AGAIN",fn:startNew},{label:"REVISIT THE LETTER",secondary:true,fn:openLetter}])}
