function drawTrain(x,y,green){ctx.save();ctx.shadowColor=green?"#77e3bf99":"#ffc98088";ctx.shadowBlur=green?18:5;round(x,y-64,230,64,12,green?"#536c68":"#4b3c49","#2e2c37");ctx.fillStyle="#eccb8a";ctx.fillRect(x+15,y-48,28,20);ctx.fillRect(x+58,y-48,28,20);ctx.fillRect(x+101,y-48,28,20);ctx.fillStyle="#d7c4a0";ctx.fillRect(x+151,y-53,35,18);ctx.fillStyle="#282832";for(var i=0;i<3;i++){ctx.beginPath();ctx.arc(x+43+i*67,y+1,10,0,Math.PI*2);ctx.fill()}ctx.restore()}
function glow(x,y,r,c){var g=ctx.createRadialGradient(x,y,2,x,y,r);g.addColorStop(0,c);g.addColorStop(1,"#ffffff00");ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2)}
function frame(now){var dt=Math.max(0,Math.min(.034,(now-lastTime)/1000));lastTime=now;update(dt);drawAll();requestAnimationFrame(frame)}
var musicTimer=null,musicIndex=0,windOsc=null,windGain=null;
function musicLoop(){if(!musicOn)return;try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();var notes=[220,261.63,329.63,293.66,246.94,196,246.94,293.66],o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type="sine";o.frequency.value=notes[musicIndex++%notes.length];g.gain.setValueAtTime(.0001,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.013,audioCtx.currentTime+.16);g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+1.05);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+1.08);if(!windOsc){windOsc=audioCtx.createOscillator();windGain=audioCtx.createGain();windOsc.type="triangle";windOsc.frequency.value=74;windGain.gain.value=.003;windOsc.connect(windGain);windGain.connect(audioCtx.destination);windOsc.start()}}catch(e){}musicTimer=setTimeout(musicLoop,1200)}
function setMusic(on){musicOn=on;if(musicTimer){clearTimeout(musicTimer);musicTimer=null}if(on){musicLoop()}else if(windOsc){try{windOsc.stop()}catch(e){}windOsc=null;windGain=null}}
function playSound(freq,dur){if(!soundOn)return;try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();var o=audioCtx.createOscillator(),g=audioCtx.createGain();o.frequency.value=freq;o.type="sine";g.gain.value=.02;o.connect(g);g.connect(audioCtx.destination);o.start();g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+dur);o.stop(audioCtx.currentTime+dur)}catch(e){}}
