document.getElementById("soundBtn").onclick=function(){soundOn=!soundOn;toast(soundOn?"Sound on":"Sound off")};document.getElementById("musicBtn").onclick=function(){setMusic(!musicOn);toast(musicOn?"Soft ambience on":"Music off")};
document.getElementById("dialogueNext").onclick=function(e){e.stopPropagation();nextLine()};dialogue.onclick=nextLine;
document.addEventListener("keydown",function(e){var k=e.key.toLowerCase();if([" ","enter","arrowup","arrowdown","arrowleft","arrowright"].includes(k))e.preventDefault();if(k==="escape"){if(!overlay.classList.contains("closed"))closePanel();else menu();return}if(k==="arrowleft"||k==="a")keys.left=true;if(k==="arrowright"||k==="d")keys.right=true;if((k===" "||k==="arrowup"||k==="w")&&!e.repeat){if(dialogueOpen)nextLine();else jumpQueued=true}if(k==="j"&&!e.repeat)attackQueued=true;if(k==="e"||k==="enter"){if(dialogueOpen)nextLine();else interact()}if(k==="shift")keys.run=true});
document.addEventListener("keyup",function(e){var k=e.key.toLowerCase();if(k==="arrowleft"||k==="a")keys.left=false;if(k==="arrowright"||k==="d")keys.right=false;if(k==="shift")keys.run=false});
document.querySelectorAll("[data-hold]").forEach(function(b){var k=b.dataset.hold;b.addEventListener("pointerdown",function(e){e.preventDefault();keys[k]=true;b.setPointerCapture(e.pointerId)});["pointerup","pointercancel","lostpointercapture"].forEach(function(ev){b.addEventListener(ev,function(){keys[k]=false})})});
document.querySelectorAll("[data-action]").forEach(function(b){b.addEventListener("pointerdown",function(e){e.preventDefault();if(b.dataset.action==="jump")jumpQueued=true;else if(b.dataset.action==="interact"){if(dialogueOpen)nextLine();else interact()}else attackQueued=true})});
